async function importProducts() {
  console.log(`Importing ${products.length} products...`)
  
  // Delete old eBay products
  const { error: delError } = await supabase
    .from('products')
    .delete()
    .eq('source', 'ebay')
  
  if (delError) console.log('Note:', delError.message)
  else console.log('Old eBay products cleared')
  
  const BATCH = 50
  let success = 0
  
  for (let i = 0; i < products.length; i += BATCH) {
    const batch = products.slice(i, i + BATCH).map(p => ({
      title: p.title,
      price: p.currency === 'USD' ? Math.round(p.price * 1.38 * 100) / 100 : p.price,
      currency: 'CAD',
      stock: p.stock || 1,
      condition: p.condition || 'New',
      category: p.category,
      photos: p.photos || [],
      ebay_id: p.ebay_id,
      enabled: true,
      source: 'ebay',
      weight: 250,
      watchers: 0,
      sold: 0,
    }))
    
    const { error } = await supabase.from('products').insert(batch)
    if (error) console.error(`Batch ${Math.floor(i/BATCH) + 1} error:`, error.message)
    else {
      success += batch.length
      console.log(`✓ ${success}/${products.length} imported`)
    }
  }
  
  console.log(`\n✅ Done! ${success} products imported into Supabase.`)
}

importProducts().catch(console.error)
